import { Injectable } from '@angular/core';
import type {
  PDFDocumentLoadingTask,
  PDFDocumentProxy,
  PDFPageProxy,
  PageViewport,
  RenderTask,
} from 'pdfjs-dist';
import type {
  PdfDocumentHandle,
  PdfEngine,
  PdfPageRenderResult,
  PdfSearchMatch,
  PdfSearchOptions,
} from '../../components/pdf-viewer/pdf-engine.interface';

type PdfJsLib = typeof import('pdfjs-dist');
type TextContent = Awaited<ReturnType<PDFPageProxy['getTextContent']>>;

const MAX_BITMAP_CACHE = 6;

/**
 * Backward-compat aliases for the pdf.js-era type names. They resolve to
 * the engine-agnostic types from `pdf-engine.interface`. Dropped in Phase 4
 * when pdf.js leaves the codebase.
 */
export type PdfJsRenderResult = PdfPageRenderResult;
export type PdfJsSearchMatch = PdfSearchMatch;
export type PdfJsDocumentHandle = PdfDocumentHandle;

function makeRenderTextLayer(
  lib: PdfJsLib,
  getTextContent: (index: number) => Promise<TextContent>,
  index: number,
  viewport: PageViewport,
): (container: HTMLElement) => Promise<void> {
  return async (container) => {
    const textContent = await getTextContent(index);
    const temp = document.createElement('div');
    temp.style.cssText = `position: absolute; left: -100000px; top: 0; width: ${viewport.width}px; height: ${viewport.height}px; visibility: hidden;`;
    document.body.appendChild(temp);
    try {
      const textLayer = new lib.TextLayer({
        textContentSource: textContent,
        container: temp,
        viewport,
      });
      await textLayer.render();
      container.style.width = `${viewport.width}px`;
      container.style.height = `${viewport.height}px`;
      container.replaceChildren(...Array.from(temp.children));
    } finally {
      temp.remove();
    }
  };
}

@Injectable({ providedIn: 'root' })
export class PdfRenderService implements PdfEngine {
  #libPromise?: Promise<PdfJsLib>;

  /** Implements {@link PdfEngine.load}. */
  async load(bytes: Uint8Array): Promise<PdfDocumentHandle> {
    const lib = await this.#getLib();
    const data = bytes.slice();
    const loadingTask = lib.getDocument({ data });
    const doc = await loadingTask.promise;
    return this.#wrap(lib, loadingTask, doc);
  }

  #getLib(): Promise<PdfJsLib> {
    if (!this.#libPromise) {
      this.#libPromise = import('pdfjs-dist').then((lib) => {
        lib.GlobalWorkerOptions.workerSrc = 'assets/pdf.worker.min.mjs';
        return lib;
      });
    }
    return this.#libPromise;
  }

  #wrap(
    lib: PdfJsLib,
    loadingTask: PDFDocumentLoadingTask,
    doc: PDFDocumentProxy,
  ): PdfDocumentHandle {
    const pageCache = new Map<number, Promise<PDFPageProxy>>();
    const textContentCache = new Map<number, Promise<TextContent>>();
    const pageTextCache = new Map<number, Promise<{ text: string; itemOffsets: number[] }>>();
    const bitmapCache = new Map<string, ImageBitmap>();
    const activeRenders = new Map<number, RenderTask>();
    let closed = false;

    const cancelAllRenders = () => {
      for (const task of activeRenders.values()) task.cancel();
      activeRenders.clear();
    };

    const getPage = (index: number) => {
      const cached = pageCache.get(index);
      if (cached) return cached;
      const promise = doc.getPage(index + 1);
      pageCache.set(index, promise);
      return promise;
    };

    const getTextContent = (index: number) => {
      const cached = textContentCache.get(index);
      if (cached) return cached;
      const promise = getPage(index).then((page) => page.getTextContent());
      textContentCache.set(index, promise);
      return promise;
    };

    const getPageText = (index: number) => {
      const cached = pageTextCache.get(index);
      if (cached) return cached;
      const promise = getTextContent(index).then((tc) => {
        let text = '';
        const itemOffsets: number[] = [];
        for (const item of tc.items as Array<{ str?: string; hasEOL?: boolean }>) {
          itemOffsets.push(text.length);
          text += item.str ?? '';
          if (item.hasEOL) text += '\n';
        }
        itemOffsets.push(text.length);
        return { text, itemOffsets };
      });
      pageTextCache.set(index, promise);
      return promise;
    };

    const cacheKey = (index: number, scale: number) => `${index}@${scale.toFixed(3)}`;

    const touch = (key: string) => {
      const v = bitmapCache.get(key);
      if (!v) return;
      bitmapCache.delete(key);
      bitmapCache.set(key, v);
    };

    const evict = () => {
      while (bitmapCache.size > MAX_BITMAP_CACHE) {
        const oldestKey = bitmapCache.keys().next().value;
        if (oldestKey === undefined) break;
        const oldest = bitmapCache.get(oldestKey);
        bitmapCache.delete(oldestKey);
        oldest?.close();
      }
    };

    const clearBitmapCache = () => {
      for (const bm of bitmapCache.values()) bm.close();
      bitmapCache.clear();
    };

    return {
      pageCount: doc.numPages,
      getPageSize: async (index, scale) => {
        if (closed) throw new Error('PDF document is closed');
        const page = await getPage(index);
        const viewport = page.getViewport({ scale });
        return { width: viewport.width, height: viewport.height };
      },
      renderPage: async (index, scale, canvas) => {
        if (closed) throw new Error('PDF document is closed');
        const page = await getPage(index);
        const viewport = page.getViewport({ scale });
        const w = Math.floor(viewport.width);
        const h = Math.floor(viewport.height);

        const swapToVisible = (source: CanvasImageSource) => {
          canvas.width = w;
          canvas.height = h;
          const ctx = canvas.getContext('2d');
          if (!ctx) throw new Error('Could not acquire 2D canvas context');
          ctx.drawImage(source, 0, 0);
        };

        const key = cacheKey(index, scale);
        const cached = bitmapCache.get(key);
        if (cached) {
          swapToVisible(cached);
          touch(key);
          return {
            renderTextLayer: makeRenderTextLayer(lib, getTextContent, index, viewport),
          };
        }

        const offscreen = new OffscreenCanvas(w, h);
        const offCtx = offscreen.getContext('2d');
        if (!offCtx) throw new Error('Could not acquire offscreen 2D context');
        activeRenders.get(index)?.cancel();
        const task = page.render({
          canvasContext: offCtx as unknown as CanvasRenderingContext2D,
          canvas: offscreen as unknown as HTMLCanvasElement,
          viewport,
        });
        activeRenders.set(index, task);
        try {
          await task.promise;
        } finally {
          if (activeRenders.get(index) === task) activeRenders.delete(index);
        }

        if (closed) {
          return {
            renderTextLayer: async () => {},
          };
        }

        swapToVisible(offscreen);

        try {
          const bitmap = offscreen.transferToImageBitmap();
          if (closed) {
            bitmap.close();
          } else {
            bitmapCache.set(key, bitmap);
            evict();
          }
        } catch {
          // best-effort cache; ignore failures
        }

        return {
          renderTextLayer: makeRenderTextLayer(lib, getTextContent, index, viewport),
        };
      },
      searchAll: async (query: string, opts?: PdfSearchOptions): Promise<PdfSearchMatch[]> => {
        if (closed) throw new Error('PDF document is closed');
        if (!query) return [];
        const caseSensitive = opts?.caseSensitive ?? false;
        const needle = caseSensitive ? query : query.toLowerCase();
        const matches: PdfSearchMatch[] = [];
        for (let p = 0; p < doc.numPages; p++) {
          if (closed) return [];
          const { text, itemOffsets } = await getPageText(p);
          const haystack = caseSensitive ? text : text.toLowerCase();
          let pos = 0;
          while (true) {
            const idx = haystack.indexOf(needle, pos);
            if (idx < 0) break;
            const end = idx + needle.length;
            const itemIndices: number[] = [];
            for (let i = 0; i < itemOffsets.length - 1; i++) {
              const itemStart = itemOffsets[i];
              const itemEnd = itemOffsets[i + 1];
              if (itemStart < end && itemEnd > idx) itemIndices.push(i);
            }
            matches.push({ pageIndex: p, itemIndices });
            pos = end > idx ? end : idx + 1;
          }
        }
        return matches;
      },
      cancelActiveRender: () => {
        cancelAllRenders();
      },
      close: () => {
        if (closed) return;
        closed = true;
        cancelAllRenders();
        pageCache.clear();
        textContentCache.clear();
        pageTextCache.clear();
        clearBitmapCache();
        loadingTask.destroy();
      },
    };
  }
}
