import { afterRenderEffect, Directive, ElementRef, inject } from '@angular/core';

@Directive({
  selector: 'textarea[ommGrow]',
  host: {
    '[attr.rows]': '1'
  }
})
export class GrowingTextarea {
  #elRef = inject(ElementRef<HTMLTextAreaElement>);

  constructor() {
    afterRenderEffect(() => {
      const textarea = this.#elRef.nativeElement;
      const maxHeight = 240;
      const resize = () => {
        textarea.style.height = 'auto';
        const height = Math.min(textarea.scrollHeight, maxHeight);
        textarea.style.height = height ? `${height}px` : 'var(--line-height)';
        textarea.style.overflowY = textarea.scrollHeight > maxHeight ? 'auto' : 'hidden';
      };
      resize(); // initial size
      textarea.addEventListener('input', resize);
      return () => {
        textarea.removeEventListener('input', resize);
      };
    });
  }
}
