import {
  booleanAttribute,
  Component,
  computed,
  contentChildren,
  DestroyRef,
  effect,
  inject,
  input,
  output,
  signal,
  untracked,
} from '@angular/core';
import { FocusKeyManager } from '@angular/cdk/a11y';
import { takeUntilDestroyed } from '@angular/core/rxjs-interop';
import { Subscription } from 'rxjs';
import { DragSelect } from '../../directives/drag-select';
import { ListItem } from './list-item';
import { EnvironmentService } from '../../services/environment.service';


@Component({
  selector: 'omm-list',
  imports: [DragSelect],
  templateUrl: './list.html',
  styleUrl: './list.scss',
  host: {
    role: 'listbox',
    'aria-orientation': 'vertical',
    '[attr.aria-multiselectable]': 'multi() || null',
    '(keydown)': 'onKeyDown($event)',
  },
})
export class List<T> {
  #dRef = inject(DestroyRef);
  #env = inject(EnvironmentService);

  multi = input(false, { transform: booleanAttribute });
  /**
   * When true, a plain click (no modifier, not in selection mode) activates the
   * item instead of replacing the selection. Modifier-click, shift-range,
   * drag-select and long-press still select as usual. Lets a multi-select list
   * keep "click to open" semantics (e.g. a photo grid). Default false.
   */
  activateOnClick = input(false, { transform: booleanAttribute });
  itemActivate = output<T>();
  selectionChange = output<T[]>();
  selectionModeChange = output<boolean>();

  isTouch = this.#env.isTouch;

  items = contentChildren<ListItem<T>>(ListItem);
  selectableEls = computed(() => this.items().map((i) => i.el));
  activeIndex = signal(0);
  selection = signal<ReadonlySet<number>>(new Set());
  readonly selectionMode = signal(false);

  #anchorIndex = -1;
  keyManager!: FocusKeyManager<ListItem<T>>;
  #keyManagerSubscription?: Subscription;

  #autoExitSelectionModeEffect = effect(() => {
    if (this.selectionMode() && this.selection().size === 0) {
      untracked(() => {
        this.selectionMode.set(false);
        this.selectionModeChange.emit(false);
      });
    }
  });

  #itemsEffect = effect(() => {
    const items = this.items();
    if (this.#keyManagerSubscription) this.#keyManagerSubscription.unsubscribe();
    if (this.keyManager) this.keyManager.destroy();

    this.keyManager = new FocusKeyManager(items).withWrap().withHomeAndEnd().withTypeAhead();
    untracked(() => this.keyManager.setActiveItem(this.activeIndex()));

    this.#keyManagerSubscription = this.keyManager.change
      .pipe(takeUntilDestroyed(this.#dRef))
      .subscribe((index) => {
        if (index != null) this.activeIndex.set(index);
      });
  });

  isSelected(index: number): boolean {
    return this.selection().has(index);
  }

  #isSelectable(index: number): boolean {
    return this.items()[index]?.selectable() ?? true;
  }

  onKeyDown(event: KeyboardEvent) {
    const items = this.items();
    if (!items.length) return;

    // Don't hijack typing inside a row's own input (e.g. inline rename).
    const target = event.target as HTMLElement;
    if (target.tagName === 'INPUT' || target.tagName === 'TEXTAREA') return;

    if (event.key === ' ' || event.key === 'Spacebar') {
      const index = this.activeIndex();
      if (!this.#isSelectable(index)) {
        // Non-selectable rows (e.g. folders) activate instead of toggling.
        event.preventDefault();
        this.handleItemActivate(index);
        return;
      }
      if (this.multi()) {
        event.preventDefault();
        this.#toggleAt(index);
      }
      return;
    }
    if (event.key === 'Enter') {
      event.preventDefault();
      const value = items[this.activeIndex()]?.value();
      if (value !== undefined) this.itemActivate.emit(value);
      return;
    }
    this.keyManager.onKeydown(event);
  }

  handleItemClick(index: number, event: MouseEvent) {
    const items = this.items();
    const value = items[index]?.value();
    if (value === undefined) return;
    if (!this.#isSelectable(index)) {
      this.handleItemActivate(index);
      return;
    }

    if (!this.multi()) {
      this.selection.set(new Set([index]));
      this.activeIndex.set(index);
      this.#emitSelection();
      return;
    }

    if (this.selectionMode()) {
      this.#toggleAt(index);
      this.activeIndex.set(index);
      return;
    }

    if (event.shiftKey && this.#anchorIndex >= 0) {
      const [a, b] = [this.#anchorIndex, index].sort((x, y) => x - y);
      const next = new Set<number>();
      for (let i = a; i <= b; i++) if (this.#isSelectable(i)) next.add(i);
      this.selection.set(next);
    } else if (event.ctrlKey || event.metaKey) {
      const next = new Set(this.selection());
      if (next.has(index)) next.delete(index);
      else next.add(index);
      this.selection.set(next);
      this.#anchorIndex = index;
    } else if (this.activateOnClick()) {
      // Plain click opens the item rather than replacing the selection.
      this.handleItemActivate(index);
      return;
    } else {
      this.selection.set(new Set([index]));
      this.#anchorIndex = index;
    }
    this.activeIndex.set(index);
    this.#emitSelection();
  }

  handleItemActivate(index: number) {
    const value = this.items()[index]?.value();
    if (value === undefined) return;
    this.itemActivate.emit(value);
  }

  selectItem(index: number) {
    const items = this.items();
    if (index < 0 || index >= items.length) return;
    this.selection.set(new Set([index]));
    this.activeIndex.set(index);
    this.#anchorIndex = index;
    this.#emitSelection();
  }

  clearSelection() {
    if (this.selection().size === 0) return;
    this.selection.set(new Set());
    this.#anchorIndex = -1;
    this.#emitSelection();
  }

  enterSelectionMode(index: number) {
    if (!this.multi()) return;
    const items = this.items();
    if (index < 0 || index >= items.length) return;
    if (!this.#isSelectable(index)) return;
    const value = items[index].value();
    if (value === undefined) return;
    const wasOn = this.selectionMode();
    this.selection.set(new Set([index]));
    this.activeIndex.set(index);
    this.#anchorIndex = index;
    if (!wasOn) {
      this.selectionMode.set(true);
      this.selectionModeChange.emit(true);
    }
    this.#emitSelection();
  }

  exitSelectionMode() {
    const wasOn = this.selectionMode();
    const hadSelection = this.selection().size > 0;
    if (hadSelection) {
      this.selection.set(new Set());
      this.#anchorIndex = -1;
      this.#emitSelection();
    }
    if (wasOn) {
      this.selectionMode.set(false);
      this.selectionModeChange.emit(false);
    }
  }

  onDragSelectChange(indices: number[]) {
    if (!this.multi()) return;
    this.selection.set(new Set(indices.filter((i) => this.#isSelectable(i))));
    this.#emitSelection();
  }

  #toggleAt(index: number) {
    const next = new Set(this.selection());
    if (next.has(index)) next.delete(index);
    else next.add(index);
    this.selection.set(next);
    this.#anchorIndex = index;
    this.#emitSelection();
  }

  #emitSelection() {
    const items = this.items();
    this.selectionChange.emit(
      [...this.selection()].map((i) => items[i].value()).filter((v): v is T => v !== undefined),
    );
  }
}
