import { Component, computed, ElementRef, forwardRef, inject, input, signal, viewChild } from '@angular/core';
import { AbstractControl, ControlValueAccessor, NG_VALIDATORS, NG_VALUE_ACCESSOR, ValidationErrors, Validator } from '@angular/forms';
import { Calendar1Icon, LucideAngularModule } from 'lucide-angular';
import { DatepickerService } from './datepicker.service';
import { Calendar } from './calendar/calendar';

@Component({
  selector: 'omm-datepicker',
  imports: [LucideAngularModule, Calendar],
  templateUrl: './datepicker.html',
  styleUrl: './datepicker.scss',
    providers: [
    {
      provide: NG_VALUE_ACCESSOR,
      useExisting: forwardRef(() => Datepicker),
      multi: true,
    },
    {
      provide: NG_VALIDATORS,
      useExisting: forwardRef(() => Datepicker),
      multi: true,
    },
  ],
})
export class Datepicker implements ControlValueAccessor, Validator {
  readonly icon = Calendar1Icon;
private readonly localeService = inject(DatepickerService);

  readonly min = input<Date | null>(null);

  protected readonly selectedDate = signal<Date | null>(null);
  protected readonly inputValue = signal<string>('');
  protected readonly disabled = signal<boolean>(false);

  protected readonly calendarDialog =
    viewChild.required<ElementRef<HTMLDialogElement>>('calendarDialog');
  protected readonly triggerButton =
    viewChild.required<ElementRef<HTMLButtonElement>>('triggerButton');
  protected readonly calendarRef = viewChild.required(Calendar);

  protected readonly dateFormatPlaceholder = this.localeService.getDateFormatPlaceholder();

  protected readonly chooseButtonAriaLabel = computed(() => {
    const date = this.selectedDate();
    if (!date) return 'Choose Date';
    return `Change Date, ${this.localeService.getFullDateLabel(date)}`;
  });

  protected readonly initialFocusDate = computed(() => this.selectedDate() ?? new Date());

  private onChange: (value: Date | null) => void = () => {};
  protected onTouched: () => void = () => {};

  writeValue(value: Date | string | null): void {

    if(typeof value === 'string' ) value = new Date(value)

    this.selectedDate.set(value);

    this.inputValue.set(value ? this.localeService.formatDateForInput(value) : '');
  }

  registerOnChange(fn: (value: Date | null) => void): void {
    this.onChange = fn;
  }

  registerOnTouched(fn: () => void): void {
    this.onTouched = fn;
  }

  setDisabledState(isDisabled: boolean): void {
    this.disabled.set(isDisabled);
  }

  validate(_control: AbstractControl): ValidationErrors | null {
    const raw = this.inputValue();
    if (raw && !this.selectedDate()) {
      return { datepickerParse: { value: raw } };
    }
    const date = this.selectedDate();
    const minDate = this.min();
    if (date && minDate) {
      const minNorm = new Date(minDate.getFullYear(), minDate.getMonth(), minDate.getDate());
      if (date.getTime() < minNorm.getTime()) {
        return { datepickerMin: { min: minDate, actual: date } };
      }
    }
    return null;
  }

  protected onManualInput(event: Event): void {
    const raw = (event.target as HTMLInputElement).value;
    this.inputValue.set(raw);
    const parsed = this.localeService.parseDateFromInput(raw);
    this.selectedDate.set(parsed);
    this.onChange(parsed);
  }

  protected toggleDialog(): void {
    const dialog = this.calendarDialog().nativeElement;
    if (dialog.open) {
      dialog.close();
    } else {
      dialog.showModal();
      // Wait one tick for dialog to be visible, then focus the active cell
      setTimeout(() => this.calendarRef().focusActiveCell());
    }
  }

  protected onDateSelected(date: Date): void {
    this.selectedDate.set(date);
    this.inputValue.set(this.localeService.formatDateForInput(date));
    this.onChange(date);
    this.calendarDialog().nativeElement.close();
  }

  protected onDialogClose(): void {
    this.onTouched();
    this.triggerButton().nativeElement.focus();
  }

  protected onDialogBackdropClick(event: MouseEvent): void {
    if (event.target === this.calendarDialog().nativeElement) {
      this.calendarDialog().nativeElement.close();
    }
  }
}
