import { OverlayModule } from '@angular/cdk/overlay';
import {
  booleanAttribute,
  ChangeDetectionStrategy,
  Component,
  computed,
  effect,
  ElementRef,
  inject,
  input,
  model,
  output,
  signal,
  untracked,
  viewChildren,
} from '@angular/core';
import { FormsModule } from '@angular/forms';
import {
  ChevronDownIcon,
  ChevronRightIcon,
  LucideAngularModule,
  PlusIcon,
  Trash2Icon,
} from 'lucide-angular';
import { ConfirmService } from '../../services/confirm.service';
import { CollectionTreeLabels, TreeNode } from './tree-node.interface';

interface FlatNode {
  node: TreeNode;
  depth: number;
  hasChildren: boolean;
  expanded: boolean;
}

@Component({
  selector: 'omm-collection-tree',
  imports: [FormsModule, LucideAngularModule],
  templateUrl: './collection-tree.html',
  styleUrl: './collection-tree.scss',
  changeDetection: ChangeDetectionStrategy.OnPush,
  host: {
    role: 'tree',
    '(keydown)': 'onHostKeydown($event)',
  },
})
export class CollectionTree {
  #confirm = inject(ConfirmService);

  readonly nodes = input.required<readonly TreeNode[]>();
  readonly editable = input(false, { transform: booleanAttribute });
  readonly selectedId = model<string | undefined>(undefined);
  readonly labels = input<CollectionTreeLabels>({});

  readonly addRequest = output<{ parentId?: string }>();
  readonly renameRequest = output<{ id: string; name: string }>();
  readonly deleteRequest = output<{ id: string }>();

  protected readonly addIcon = PlusIcon;
  protected readonly deleteIcon = Trash2Icon;
  protected readonly chevronDownIcon = ChevronDownIcon;
  protected readonly chevronRightIcon = ChevronRightIcon;

  protected readonly expanded = signal<ReadonlySet<string>>(new Set());
  protected readonly activeId = signal<string | undefined>(undefined);
  protected readonly menuOpenFor = signal<string | undefined>(undefined);

  /**
   * When set (via {@link editNode}), the next render focuses and selects the
   * name input for that node id, then clears this signal. Used to start
   * inline editing right after the consumer creates a new node.
   */
  protected readonly pendingEditId = signal<string | undefined>(undefined);

  protected readonly rowEls =
    viewChildren<ElementRef<HTMLLIElement>>('row');

  #pendingEditEffect = effect(() => {
    const pending = this.pendingEditId();
    const rows = this.rowEls();
    if (!pending) return;
    const row = rows.find((r) => r.nativeElement.dataset['id'] === pending);
    if (!row) return;
    untracked(() => {
      const input = row.nativeElement.querySelector<HTMLInputElement>(
        'input.name-input',
      );
      if (input) {
        input.focus();
        input.select();
      }
      this.pendingEditId.set(undefined);
    });
  });

  /**
   * Reveals the selected node when `selectedId` is set (e.g. a consumer opening
   * the tree with an existing value): expands its ancestor chain so the
   * highlighted row is visible, then scrolls it into view. A no-op when the
   * node is already visible, so it doesn't interfere with normal clicks.
   */
  #revealSelectedEffect = effect(() => {
    const id = this.selectedId();
    const all = this.nodes();
    if (!id) return;
    untracked(() => {
      const byId = new Map(all.map((n) => [n.id, n]));
      const next = new Set(this.expanded());
      let changed = false;
      let cursor = byId.get(id)?.parentId;
      while (cursor && !next.has(cursor)) {
        next.add(cursor);
        changed = true;
        cursor = byId.get(cursor)?.parentId;
      }
      if (changed) this.expanded.set(next);
      queueMicrotask(() => this.#findRowEl(id)?.scrollIntoView({ block: 'nearest' }));
    });
  });

  protected readonly flat = computed<FlatNode[]>(() => {
    const all = this.nodes();
    const byParent = new Map<string | undefined, TreeNode[]>();
    for (const n of all) {
      const list = byParent.get(n.parentId) ?? [];
      list.push(n);
      byParent.set(n.parentId, list);
    }
    for (const list of byParent.values()) {
      list.sort((a, b) => a.name.localeCompare(b.name));
    }
    const exp = this.expanded();
    const out: FlatNode[] = [];
    const walk = (parentId: string | undefined, depth: number) => {
      const children = byParent.get(parentId) ?? [];
      for (const c of children) {
        const grand = byParent.get(c.id) ?? [];
        const isExpanded = exp.has(c.id);
        out.push({
          node: c,
          depth,
          hasChildren: grand.length > 0,
          expanded: isExpanded,
        });
        if (isExpanded) walk(c.id, depth + 1);
      }
    };
    walk(undefined, 0);
    return out;
  });

  /** Imperative API: focus a row's name input so the user can rename it. */
  editNode(id: string): void {
    // Expand all ancestors so the node is visible.
    const all = this.nodes();
    const byId = new Map(all.map((n) => [n.id, n]));
    const next = new Set(this.expanded());
    let cursor = byId.get(id)?.parentId;
    while (cursor) {
      next.add(cursor);
      cursor = byId.get(cursor)?.parentId;
    }
    this.expanded.set(next);
    this.activeId.set(id);
    this.pendingEditId.set(id);
  }

  protected toggleExpanded(id: string, event?: Event): void {
    event?.stopPropagation();
    const next = new Set(this.expanded());
    if (next.has(id)) next.delete(id);
    else next.add(id);
    this.expanded.set(next);
  }

  protected onRowClick(node: TreeNode): void {
    this.activeId.set(node.id);
    if (!this.editable()) {
      this.selectedId.set(node.id);
    }
  }

  protected onNameClick(node: TreeNode, event: Event): void {
    event.stopPropagation();
    this.activeId.set(node.id);
    if (!this.editable()) {
      this.selectedId.set(node.id);
    }
  }

  protected onAddChild(parentId: string, event: Event): void {
    event.stopPropagation();
    // Auto-expand the parent so the new child is visible.
    const next = new Set(this.expanded());
    next.add(parentId);
    this.expanded.set(next);
    this.addRequest.emit({ parentId });
  }

  protected async onDeleteClick(node: TreeNode): Promise<void> {
    const l = this.labels();
    const message = (l.deleteMessage ?? 'Delete "{{name}}"?').replace(
      '{{name}}',
      node.name,
    );
    const ok = await this.#confirm.confirm(
      message,
      l.deleteTitle,
      l.delete,
    );
    if (!ok) return;
    this.deleteRequest.emit({ id: node.id });
  }

  protected onNameInputCommit(node: TreeNode, event: Event): void {
    const input = event.target as HTMLInputElement;
    const value = input.value.trim();
    if (!value || value === node.name) {
      input.value = node.name;
      return;
    }
    this.renameRequest.emit({ id: node.id, name: value });
  }

  protected onNameInputKeydown(node: TreeNode, event: KeyboardEvent): void {
    if (event.key === 'Enter') {
      event.preventDefault();
      (event.target as HTMLInputElement).blur();
    } else if (event.key === 'Escape') {
      event.preventDefault();
      (event.target as HTMLInputElement).value = node.name;
      (event.target as HTMLInputElement).blur();
    }
  }

  protected onNameInputFocus(id: string): void {
    this.activeId.set(id);
    if (this.pendingEditId() === id) {
      this.pendingEditId.set(undefined);
    }
  }

  protected onHostKeydown(event: KeyboardEvent): void {
    const flat = this.flat();
    if (!flat.length) return;
    const currentId = this.activeId() ?? flat[0].node.id;
    const idx = flat.findIndex((f) => f.node.id === currentId);
    if (idx < 0) return;
    const current = flat[idx];

    const target = event.target as HTMLElement;
    const inInput = target.tagName === 'INPUT';

    switch (event.key) {
      case 'ArrowDown': {
        event.preventDefault();
        const next = flat[Math.min(idx + 1, flat.length - 1)];
        this.#focusRow(next.node.id, inInput);
        break;
      }
      case 'ArrowUp': {
        event.preventDefault();
        const next = flat[Math.max(idx - 1, 0)];
        this.#focusRow(next.node.id, inInput);
        break;
      }
      case 'Home': {
        event.preventDefault();
        this.#focusRow(flat[0].node.id, inInput);
        break;
      }
      case 'End': {
        event.preventDefault();
        this.#focusRow(flat[flat.length - 1].node.id, inInput);
        break;
      }
      case 'ArrowRight': {
        if (inInput) return; // let cursor move
        if (current.hasChildren && !current.expanded) {
          event.preventDefault();
          this.toggleExpanded(current.node.id);
        } else if (current.hasChildren && current.expanded) {
          event.preventDefault();
          const child = flat[idx + 1];
          if (child) this.#focusRow(child.node.id, false);
        }
        break;
      }
      case 'ArrowLeft': {
        if (inInput) return;
        if (current.expanded) {
          event.preventDefault();
          this.toggleExpanded(current.node.id);
        } else if (current.node.parentId) {
          event.preventDefault();
          this.#focusRow(current.node.parentId, false);
        }
        break;
      }
      case 'Enter': {
        if (inInput) return; // handled by input keydown
        event.preventDefault();
        if (this.editable()) {
          this.#focusInputFor(current.node.id);
        } else {
          this.selectedId.set(current.node.id);
        }
        break;
      }
      case ' ': {
        if (inInput) return;
        if (!this.editable()) {
          event.preventDefault();
          this.selectedId.set(current.node.id);
        }
        break;
      }
      case 'F2': {
        if (this.editable()) {
          event.preventDefault();
          this.#focusInputFor(current.node.id);
        }
        break;
      }
      case 'Delete': {
        if (inInput) return;
        if (this.editable()) {
          event.preventDefault();
          void this.onDeleteClick(current.node);
        }
        break;
      }
    }
  }

  #focusRow(id: string, intoInput: boolean): void {
    this.activeId.set(id);
    queueMicrotask(() => {
      const row = this.#findRowEl(id);
      if (!row) return;
      if (intoInput && this.editable()) {
        const input = row.querySelector<HTMLInputElement>('input.name-input');
        input?.focus();
        input?.select();
      } else {
        row.focus();
      }
    });
  }

  #focusInputFor(id: string): void {
    const row = this.#findRowEl(id);
    const input = row?.querySelector<HTMLInputElement>('input.name-input');
    input?.focus();
    input?.select();
  }

  #findRowEl(id: string): HTMLLIElement | undefined {
    for (const ref of this.rowEls()) {
      if (ref.nativeElement.dataset['id'] === id) return ref.nativeElement;
    }
    return undefined;
  }
}
