import {
  afterRenderEffect,
  Component,
  computed,
  effect,
  ElementRef,
  forwardRef,
  input,
  output,
  signal,
  untracked,
  viewChild,
  viewChildren,
} from '@angular/core';
import { Listbox, Option } from '@angular/aria/listbox';
import { ArrowDownIcon, ChevronDown, LucideAngularModule } from 'lucide-angular';
import { OverlayModule } from '@angular/cdk/overlay';
import { SelectOption } from './select.interface';
import {
  AbstractControl,
  ControlValueAccessor,
  NG_VALUE_ACCESSOR,
  ValidationErrors,
} from '@angular/forms';

let nextId = 0;
@Component({
  selector: 'omm-select',
  imports: [LucideAngularModule, OverlayModule],
  templateUrl: './select.html',
  styleUrl: './select.scss',
  providers: [
    {
      provide: NG_VALUE_ACCESSOR,
      useExisting: forwardRef(() => Select),
      multi: true,
    },
  ],
})
export class Select<T = any> implements ControlValueAccessor {
  readonly options = input.required<SelectOption<T>[]>();
  readonly required = input<boolean>(false);
  readonly disabled = input<boolean>(false);
  readonly placeholder = input<string>('');

  readonly selectionChange = output<SelectOption<T> | null>();
  readonly optionsContainerMaxHeight = 300;

  private readonly uid = nextId++;
  protected readonly isOpen = signal<boolean>(false);
  protected readonly selectedValue = signal<T | null>(null);
  protected readonly highlightedIndex = signal<number>(-1);

  protected readonly triggerButton =
    viewChild.required<ElementRef<HTMLButtonElement>>('triggerButton');
  protected readonly dropdown = viewChild.required<ElementRef<HTMLDialogElement>>('dropdown');

  protected chevronIcon = ChevronDown;

  protected readonly triggerButtonId = `app-select-trigger-${this.uid}`;
  protected readonly dropdownId = `app-select-dropdown-${this.uid}`;
  protected readonly listboxId = `app-select-listbox-${this.uid}`;

  protected readonly displayValue = computed(() => {
    const selected = this.selectedValue();
    if (!selected) return this.placeholder() || '';
    return this.options().find((opt) => this.#compareValues(opt.value, selected))?.label || '';
  });

  private onChange: (value: SelectOption<T> | null) => void = () => {};
  private onTouched: () => void = () => {};
  private clickOutsideHandler?: (event: MouseEvent) => void;

  constructor() {
    effect(() => {
      if (this.isOpen()) {
        this.clickOutsideHandler = (event: MouseEvent) => {
          const dropdown = this.dropdown()?.nativeElement;
          const trigger = this.triggerButton()?.nativeElement;
          if (
            dropdown &&
            trigger &&
            !dropdown.contains(event.target as Node) &&
            !trigger.contains(event.target as Node)
          ) {
            untracked(() => this.closeDropdown());
          }
        };
        document.addEventListener('mousedown', this.clickOutsideHandler);
        return () => {
          if (this.clickOutsideHandler) {
            document.removeEventListener('mousedown', this.clickOutsideHandler);
          }
        };
      }
      return () => {};
    });
  }

  // ControlValueAccessor
  writeValue(value: T): void {
    this.selectedValue.set(value !== null && value !== undefined ? (value as T) : null);
  }
  registerOnChange(fn: (value: SelectOption<T> | null) => void): void {
    this.onChange = fn;
  }
  registerOnTouched(fn: () => void): void {
    this.onTouched = fn;
  }
  setDisabledState(_: boolean): void {}

  // Validator
  validate(_: AbstractControl): ValidationErrors | null {
    return this.required() && !this.selectedValue() ? { required: true } : null;
  }

  // Event handlers
  protected onTriggerClick(): void {
    if (this.disabled()) return;
    this.onTouched();
    if (this.isOpen()) {
      this.closeDropdown();
    } else {
      this.#openDropdown();
    }
  }

  // When the dropdown is open, focus has moved to the option elements, so this
  // handler only needs to deal with the closed state.
  protected onTriggerKeydown(event: KeyboardEvent): void {
    if (this.disabled() || !['ArrowDown', 'Space', 'Enter'].includes(event.key)) return;
    switch (event.key) {
      case 'Enter': {
        event.preventDefault();
        break;
      }
      case 'ArrowDown':
        event.preventDefault();
        if (!this.isOpen()) this.#openDropdown();
        break;
      case 'Escape':
        if (this.isOpen()) this.closeDropdown();
        break;
    }
  }

  protected onOptionClick(option: SelectOption<T>, evt: Event): void {
    evt.preventDefault();
    if (this.disabled()) return;
    this.#selectOption(option);
    this.closeDropdown();
    this.triggerButton()?.nativeElement.focus();
  }

  protected onOptionKeydown(event: KeyboardEvent): void {
    switch (event.key) {
      case 'Enter':
        event.preventDefault();
        this.onOptionClick(this.options()[this.highlightedIndex()], event);
        break;
      case 'ArrowDown':
        event.preventDefault();
        this.#moveHighlight(1);
        break;
      case 'ArrowUp':
        event.preventDefault();
        this.#moveHighlight(-1);
        break;
      case 'Home':
        event.preventDefault();
        this.#moveHighlightToFirst();
        break;
      case 'End':
        event.preventDefault();
        this.#moveHighlightToLast();
        break;
      case 'Escape':
        event.preventDefault();
        this.closeDropdown();
        this.triggerButton()?.nativeElement.focus();
        break;
      case 'Tab':
        event.preventDefault();
        this.closeDropdown();
        this.triggerButton()?.nativeElement.focus();
        break;
    }
  }

  // Helpers
  #openDropdown(): void {
    const sv = this.selectedValue();
    const selectedIdx = sv
      ? this.options().findIndex((opt) => this.#compareValues(opt.value, sv))
      : -1;
    const initialIndex =
      selectedIdx >= 0 ? selectedIdx : this.options().findIndex((opt) => !opt.disabled);

    this.isOpen.set(true);
    this.highlightedIndex.set(initialIndex);

    requestAnimationFrame(() => {
      const dropdown = this.dropdown()?.nativeElement;
      const trigger = this.triggerButton()?.nativeElement;
      if (!dropdown || !trigger) return;

      const rect = trigger.getBoundingClientRect();
      const viewportHeight = window.innerHeight;

      // Gap between the trigger and the dropdown, and the minimum breathing
      // room we keep against the viewport edge.
      const gap = 4;
      const viewportMargin = 8;

      // The dropdown is a top-layer dialog, so it sits outside whatever padding
      // the app shell uses to stay clear of the system bars. On Android the
      // WebView runs edge-to-edge, which means `innerHeight` includes them —
      // measure against the safe area or a dropdown opening downwards near the
      // bottom ends up under the gesture bar.
      const rootStyle = getComputedStyle(document.documentElement);
      const safeTop = parseFloat(rootStyle.getPropertyValue('--omm-safe-area-top')) || 0;
      const safeBottom = parseFloat(rootStyle.getPropertyValue('--omm-safe-area-bottom')) || 0;

      const spaceBelow = viewportHeight - safeBottom - rect.bottom - gap - viewportMargin;
      const spaceAbove = rect.top - safeTop - gap - viewportMargin;

      // Prefer opening below; only flip up when below can't fit the desired
      // height and above genuinely has more room.
      const shouldOpenAbove =
        spaceBelow < this.optionsContainerMaxHeight && spaceAbove > spaceBelow;

      const available = Math.max(0, shouldOpenAbove ? spaceAbove : spaceBelow);
      const maxHeight = Math.min(this.optionsContainerMaxHeight, available);

      dropdown.style.position = 'fixed';
      dropdown.style.left = `${rect.left}px`;
      dropdown.style.width = `${rect.width}px`;
      dropdown.style.zIndex = '1000';
      dropdown.style.top = shouldOpenAbove ? 'auto' : `${rect.bottom + gap}px`;
      dropdown.style.bottom = shouldOpenAbove ? `${viewportHeight - rect.top + gap}px` : 'auto';
      dropdown.style.maxHeight = `${maxHeight}px`;

      dropdown.showModal();

      if (initialIndex >= 0) {
        document.getElementById(this.getOptionId(initialIndex))?.focus();
      } else {
        dropdown.focus();
      }
    });
  }

  protected closeDropdown(): void {
    this.isOpen.set(false);
    this.highlightedIndex.set(-1);
    const dropdown = this.dropdown()?.nativeElement;
    if (dropdown) {
      dropdown.close();
      dropdown.style.position = '';
      dropdown.style.top = '';
      dropdown.style.bottom = '';
      dropdown.style.left = '';
      dropdown.style.width = '';
      dropdown.style.maxHeight = '';
    }
  }

  #selectOption(option: SelectOption<T>): void {
    this.selectedValue.set(option.value);
    this.onChange(option.value as SelectOption<T>);
    this.selectionChange.emit(option.value as SelectOption<T>);
  }

  // Focuses the option at the given flat index and scrolls it into view.
  #focusOption(index: number): void {
    this.highlightedIndex.set(index);
    requestAnimationFrame(() => {
      const el = document.getElementById(this.getOptionId(index));
      el?.focus();
      el?.scrollIntoView({ block: 'nearest' });
    });
  }

  #moveHighlight(direction: number): void {
    const opts = this.options();
    let next = this.highlightedIndex() + direction;
    while (next >= 0 && next < opts.length && opts[next].disabled) next += direction;
    if (next >= 0 && next < opts.length) this.#focusOption(next);
  }

  #moveHighlightToFirst(): void {
    const idx = this.options().findIndex((o) => !o.disabled);
    if (idx >= 0) this.#focusOption(idx);
  }

  #moveHighlightToLast(): void {
    const opts = this.options();
    for (let i = opts.length - 1; i >= 0; i--) {
      if (!opts[i].disabled) {
        this.#focusOption(i);
        return;
      }
    }
  }

  #compareValues(a: T, b: T): boolean {
    if (a === b) return true;
    if (a && b && typeof a === 'object' && typeof b === 'object') {
      return JSON.stringify(a) === JSON.stringify(b);
    }
    return false;
  }

  // Template helpers
  protected getOptionId(flatIndex: number): string {
    return `${this.listboxId}-option-${flatIndex}`;
  }

  protected isOptionHighlighted(flatIndex: number): boolean {
    return this.highlightedIndex() === flatIndex;
  }
}
