import {
  computed,
  contentChildren,
  Directive,
  ElementRef,
  inject,
  input,
  output,
} from '@angular/core';

interface SelectableRect {
  x: number;
  y: number;
  width: number;
  height: number;
}

export interface DragSelectOptions {
  disabled?: boolean;
  selectorColor?: string;
}

@Directive({
  selector: '[ommDragSelect]',
  host: {
    '(pointerdown)': 'onPointerDown($event)',
  },
})
export class DragSelect {
  #selector?: HTMLDivElement;
  #selectStartX = 0;
  #selectStartY = 0;

  #selection: number[] = [];

  items = contentChildren(DragSelectItemDirective);
  selectables = input<readonly HTMLElement[] | undefined>(undefined);
  #selectables = computed(() => this.selectables() ?? this.items().map((item) => item.el));

  yuvDragSelect = input<DragSelectOptions>();
  dragSelectChange = output<number[]>();
  dragSelect = output<number[]>();

  onPointerDown(event: PointerEvent) {
    if (event.pointerType === 'touch') return;
    if (this.yuvDragSelect()?.disabled || (event.target as HTMLElement).tagName === 'BUTTON')
      return;
    event.preventDefault();
    this.#selectStartX = event.pageX;
    this.#selectStartY = event.pageY;

    const div = document.createElement('div');
    div.style.position = 'absolute';
    div.style.width = '0';
    div.style.height = '0';
    div.style.left = this.#selectStartX + 'px';
    div.style.top = this.#selectStartY + 'px';
    div.style.background = 'rgb(from var(--omm-accent) r g b / .2)';
    div.style.outline = '1px solid rgb(from var(--omm-accent) r g b / .6)';
    div.style.outlineOffset = '-1px';
    div.classList.add('drag-select');
    this.#selector = div;
    document.body.append(this.#selector);

    this.#selection = [];
    addEventListener('pointermove', this.#resize);
    addEventListener('pointerup', this.#onPointerUp);
  }

  #onPointerUp = () => {
    removeEventListener('pointermove', this.#resize);
    removeEventListener('pointerup', this.#onPointerUp);
    if (this.#selection.length) this.dragSelect.emit(this.#selection);
    if (this.#selector) this.#selector.remove();
  };

  #resize = (event: PointerEvent) => {
    if (!this.#selector) return;
    const diffX = event.pageX - this.#selectStartX;
    const diffY = event.pageY - this.#selectStartY;
    this.#selector.style.left =
      diffX < 0 ? this.#selectStartX + diffX + 'px' : this.#selectStartX + 'px';
    this.#selector.style.top =
      diffY < 0 ? this.#selectStartY + diffY + 'px' : this.#selectStartY + 'px';
    this.#selector.style.height = Math.abs(diffY) + 'px';
    this.#selector.style.width = Math.abs(diffX) + 'px';

    this.#selector.style.border = `1px solid ${this.yuvDragSelect()?.selectorColor || 'var(--ymt-primary'}`;
    this.#checkSelected();
  };

  #checkSelected = () => {
    if (!this.#selector) return;
    const select = this.#selector.getBoundingClientRect();
    const { x, y, height, width } = select;
    if (!height || !width) return;

    const currSelectionLength = this.#selection.length;
    this.#selectables().forEach((selectable, idx) => {
      const r1: SelectableRect = { x: x + window.scrollX, y: y + window.scrollY, height, width };
      const r2: SelectableRect = selectable.getBoundingClientRect();
      this.#selection = this.#selection.filter((s) => s !== idx);
      if (this.#checkRectIntersection(r1, r2)) {
        this.#selection.push(idx);
      }
    });

    if (currSelectionLength !== this.#selection.length) {
      this.dragSelectChange.emit(this.#selection);
    }
  };

  #checkRectIntersection = (r1: SelectableRect, r2: SelectableRect) => {
    return !(
      r1.x + r1.width < r2.x ||
      r2.x + r2.width < r1.x ||
      r1.y + r1.height < r2.y ||
      r2.y + r2.height < r1.y
    );
  };
}

@Directive({
  selector: '[yuvDragSelectItem]',
  standalone: true,
})
export class DragSelectItemDirective {
  #elRef = inject(ElementRef);
  el = this.#elRef.nativeElement as HTMLElement;
}
