import { Component, input, output } from '@angular/core';
import { LucideAngularModule, LucideIconData } from 'lucide-angular';

export interface ButtonToggleOption<T = string> {
  value: T;
  label: string;
  icon?: LucideIconData;
  ariaLabel?: string;
}

@Component({
  selector: 'omm-button-toggle',
  imports: [LucideAngularModule],
  templateUrl: './button-toggle.html',
  styleUrl: './button-toggle.scss',
})
export class ButtonToggle<T = string> {
  readonly options = input.required<ButtonToggleOption<T>[]>();
  readonly value = input.required<T>();
  readonly ariaLabel = input<string>();
  readonly iconSize = input<number>(16);
  readonly valueChange = output<T>();

  protected select(option: ButtonToggleOption<T>) {
    if (option.value !== this.value()) {
      this.valueChange.emit(option.value);
    }
  }
}
