import { Component, computed, inject, input } from '@angular/core';
import { MonitorIcon, MoonIcon, SunIcon } from 'lucide-angular';
import { ThemeMode, ThemeService } from '../../services/theme.service';
import { ButtonToggle, ButtonToggleOption } from '../button-toggle/button-toggle';

export interface ThemeToggleLabels {
  light: string;
  dark: string;
  system: string;
}

@Component({
  selector: 'omm-theme-toggle',
  imports: [ButtonToggle],
  templateUrl: './theme-toggle.html',
  styleUrl: './theme-toggle.scss',
})
export class ThemeToggle {
  readonly labels = input<ThemeToggleLabels>({ light: 'Light', dark: 'Dark', system: 'System' });

  readonly #theme = inject(ThemeService);
  protected readonly mode = this.#theme.mode;

  protected readonly options = computed<ButtonToggleOption<ThemeMode>[]>(() => {
    const l = this.labels();
    return [
      { value: 'light', label: l.light, icon: SunIcon },
      { value: 'dark', label: l.dark, icon: MoonIcon },
      { value: 'system', label: l.system, icon: MonitorIcon },
    ];
  });

  protected setMode(mode: ThemeMode) {
    this.#theme.setMode(mode);
  }
}
