import { FocusableOption } from '@angular/cdk/a11y';
import {
  booleanAttribute,
  computed,
  Directive,
  effect,
  ElementRef,
  forwardRef,
  inject,
  input,
} from '@angular/core';
import { DragSelectItemDirective } from '../../directives/drag-select';
import { List } from './list';

@Directive({
  selector: '[ommListItem]',
  exportAs: 'ommListItem',
  hostDirectives: [DragSelectItemDirective],
  host: {
    role: 'option',
    '[attr.tabindex]': 'isActive() ? 0 : -1',
    '[attr.aria-selected]': 'list.multi() ? isSelected() : null',
    '[attr.aria-disabled]': 'disabled || null',
    '[attr.data-active]': 'isActive() || null',
    '[attr.data-selected]': 'isSelected() || null',
    '[attr.data-selection-mode]': 'list.selectionMode() || null',
    '[attr.data-selectable]': 'selectable() ? null : "false"',
    '(click)': 'onClick($event)',
    '(dblclick)': 'onDblClick($event)',
    '(focus)': 'onFocus()',
    '(pointerdown)': 'onPointerDown($event)',
    '(pointermove)': 'onPointerMove($event)',
    '(pointerup)': 'onPointerEnd()',
    '(pointercancel)': 'onPointerEnd()',
    '(pointerleave)': 'onPointerEnd()',
  },
})
export class ListItem<T> implements FocusableOption {
  readonly value = input.required<T>({ alias: 'ommListItem' });
  readonly disabledInput = input(false, { transform: booleanAttribute, alias: 'disabled' });
  get disabled(): boolean {
    return this.disabledInput();
  }

  /**
   * When false, the row cannot be selected: clicks/keyboard "activate" it
   * (e.g. navigate) instead of toggling selection, and drag-select / long-press
   * selection skip it. Still focusable for keyboard navigation.
   */
  readonly selectable = input(true, { transform: booleanAttribute });

  readonly list = inject(forwardRef(() => List)) as List<T>;
  readonly el = inject<ElementRef<HTMLElement>>(ElementRef).nativeElement;

  readonly index = computed(() => this.list.items().indexOf(this));
  readonly isActive = computed(() => this.list.activeIndex() === this.index());
  readonly isSelected = computed(() => this.list.isSelected(this.index()));

  readonly #originalTabindex = new WeakMap<HTMLElement, string | null>();

  static readonly LONG_PRESS_MS = 500;
  static readonly MOVE_TOLERANCE_PX = 10;
  #longPressTimer: ReturnType<typeof setTimeout> | null = null;
  #pressStartX = 0;
  #pressStartY = 0;
  #suppressNextClick = false;

  #focusablesEffect = effect(() => {
    const active = this.isActive();
    const focusables = this.el.querySelectorAll<HTMLElement>(
      'a[href], button, input, select, textarea, [tabindex]',
    );
    focusables.forEach((el) => {
      if (el === this.el) return;
      if (!this.#originalTabindex.has(el)) {
        this.#originalTabindex.set(el, el.getAttribute('tabindex'));
      }
      if (active) {
        const orig = this.#originalTabindex.get(el)!;
        if (orig === null) el.removeAttribute('tabindex');
        else el.setAttribute('tabindex', orig);
      } else {
        el.setAttribute('tabindex', '-1');
      }
    });
  });

  focus() {
    this.el.focus();
  }

  getLabel() {
    return this.el.textContent?.trim() ?? '';
  }

  onClick(event: MouseEvent) {
    const target = event.target as HTMLElement;
    if (
      target !== this.el &&
      target.closest('button, a, input, select, textarea, [role="button"]')
    ) {
      return;
    }
    if (this.disabled) return;
    if (this.#suppressNextClick) {
      this.#suppressNextClick = false;
      return;
    }
    if (!this.selectable()) {
      // Non-selectable rows (e.g. folders) navigate on click rather than select.
      this.list.handleItemActivate(this.index());
      return;
    }
    if (this.list.isTouch() && !this.list.selectionMode()) {
      // On touch, a plain tap opens the viewer without selecting; selection mode
      // is only entered via long-press (see onPointerDown).
      this.list.handleItemActivate(this.index());
      return;
    }
    this.list.handleItemClick(this.index(), event);
  }

  onDblClick(event: MouseEvent) {
    const target = event.target as HTMLElement;
    if (
      target !== this.el &&
      target.closest('button, a, input, select, textarea, [role="button"]')
    ) {
      return;
    }
    if (this.disabled) return;
    if (this.list.isTouch()) return;
    if (this.list.selectionMode()) return;
    this.list.handleItemActivate(this.index());
  }

  onFocus() {
    if (this.list.activeIndex() !== this.index()) {
      this.list.activeIndex.set(this.index());
    }
  }

  onPointerDown(event: PointerEvent) {
    if (event.pointerType !== 'touch') return;
    if (!this.list.multi() || !this.list.isTouch()) return;
    if (this.disabled) return;
    if (!this.selectable()) return;
    if (this.list.selectionMode()) return;

    const target = event.target as HTMLElement;
    if (
      target !== this.el &&
      target.closest('button, a, input, select, textarea, [role="button"]')
    ) {
      return;
    }

    this.#pressStartX = event.clientX;
    this.#pressStartY = event.clientY;
    this.#clearLongPressTimer();
    const index = this.index();
    this.#longPressTimer = setTimeout(() => {
      this.#longPressTimer = null;
      this.#suppressNextClick = true;
      this.list.enterSelectionMode(index);
    }, ListItem.LONG_PRESS_MS);
  }

  onPointerMove(event: PointerEvent) {
    if (this.#longPressTimer === null) return;
    const dx = event.clientX - this.#pressStartX;
    const dy = event.clientY - this.#pressStartY;
    if (Math.hypot(dx, dy) > ListItem.MOVE_TOLERANCE_PX) {
      this.#clearLongPressTimer();
    }
  }

  onPointerEnd() {
    this.#clearLongPressTimer();
  }

  #clearLongPressTimer() {
    if (this.#longPressTimer !== null) {
      clearTimeout(this.#longPressTimer);
      this.#longPressTimer = null;
    }
  }
}
