import { Component, computed, forwardRef, input, signal } from '@angular/core';
import {
  AbstractControl,
  ControlValueAccessor,
  NG_VALIDATORS,
  NG_VALUE_ACCESSOR,
  ValidationErrors,
  Validator,
} from '@angular/forms';

let nextId = 0;

@Component({
  selector: 'omm-currency-input',
  standalone: true,
  templateUrl: './currency-input.html',
  styleUrl: './currency-input.scss',
  providers: [
    {
      provide: NG_VALUE_ACCESSOR,
      useExisting: forwardRef(() => CurrencyInput),
      multi: true,
    },
    {
      provide: NG_VALIDATORS,
      useExisting: forwardRef(() => CurrencyInput),
      multi: true,
    },
  ],
  host: {
    '[attr.data-symbol]': 'currency()',
  },
})
export class CurrencyInput implements ControlValueAccessor, Validator {
  private readonly locale = typeof navigator !== 'undefined' ? navigator.language : 'de-DE';

  readonly currency = input<string>('EUR');

  private readonly value = signal<number | null>(null);
  protected readonly displayValue = signal<string>('');
  protected readonly disabled = signal<boolean>(false);
  private readonly focused = signal<boolean>(false);

  private readonly uid = nextId++;
  protected readonly inputId = `app-currency-input-${this.uid}`;
  protected readonly descriptionId = `app-currency-desc-${this.uid}`;

  protected readonly currencySymbol = computed(() => {
    const parts = new Intl.NumberFormat(this.locale, {
      style: 'currency',
      currency: this.currency(),
    }).formatToParts(0);
    return parts.find((p) => p.type === 'currency')?.value ?? this.currency();
  });

  protected readonly ariaDescription = computed(() => {
    const code = this.currency();
    try {
      const names = new Intl.DisplayNames([this.locale], { type: 'currency' });
      const name = names.of(code);
      if (name) return `Enter amount in ${name}`;
    } catch {
      // Intl.DisplayNames not supported
    }
    return `Enter amount in ${code}`;
  });

  private onChange: (value: number | null) => void = () => {};
  protected onTouched: () => void = () => {};

  // ControlValueAccessor

  writeValue(value: number | null): void {
    this.value.set(value);
    if (!this.focused()) {
      this.displayValue.set(value !== null ? this.formatNumber(value) : '');
    }
  }

  registerOnChange(fn: (value: number | null) => void): void {
    this.onChange = fn;
  }

  registerOnTouched(fn: () => void): void {
    this.onTouched = fn;
  }

  setDisabledState(isDisabled: boolean): void {
    this.disabled.set(isDisabled);
  }

  // Validator

  validate(_control: AbstractControl): ValidationErrors | null {
    const raw = this.displayValue();
    if (raw.trim() && this.value() === null) {
      return { currencyInvalid: { value: raw } };
    }
    return null;
  }

  // Event handlers

  protected onFocus(): void {
    this.focused.set(true);
    const val = this.value();
    if (val !== null) {
      const decimalPlaces = this.getDecimalPlaces();
      this.displayValue.set(
        new Intl.NumberFormat(this.locale, {
          style: 'decimal',
          useGrouping: false,
          minimumFractionDigits: decimalPlaces,
          maximumFractionDigits: decimalPlaces,
        }).format(val),
      );
    }
  }

  protected onInput(event: Event): void {
    const raw = (event.target as HTMLInputElement).value;
    this.displayValue.set(raw);
    const parsed = this.parseInput(raw);
    this.value.set(parsed);
    this.onChange(parsed);
  }

  protected onBlur(): void {
    this.focused.set(false);
    this.onTouched();
    const val = this.value();
    if (val !== null) {
      this.displayValue.set(this.formatNumber(val));
    }
  }

  // Formatting

  private formatNumber(value: number): string {
    const decimalPlaces = this.getDecimalPlaces();
    return new Intl.NumberFormat(this.locale, {
      style: 'decimal',
      useGrouping: true,
      minimumFractionDigits: decimalPlaces,
      maximumFractionDigits: decimalPlaces,
    }).format(value);
  }

  private getDecimalPlaces(): number {
    return (
      new Intl.NumberFormat(this.locale, {
        style: 'currency',
        currency: this.currency(),
      }).resolvedOptions().minimumFractionDigits ?? 2
    );
  }

  // Parsing

  private parseInput(raw: string): number | null {
    if (!raw.trim()) return null;

    const parts = new Intl.NumberFormat(this.locale).formatToParts(1234567.89);
    const decimal = parts.find((p) => p.type === 'decimal')?.value ?? '.';
    const group = parts.find((p) => p.type === 'group')?.value ?? ',';

    // Escape special regex characters in separators
    const groupEscaped = group.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
    const decimalEscaped = decimal.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');

    let cleaned = raw.replace(new RegExp(groupEscaped, 'g'), '');
    if (decimal !== '.') {
      cleaned = cleaned.replace(new RegExp(decimalEscaped), '.');
    }
    // Strip non-numeric characters (currency symbols, spaces, etc.)
    cleaned = cleaned.replace(/[^0-9.\-]/g, '');

    const n = parseFloat(cleaned);
    return isNaN(n) ? null : n;
  }
}
