import { Component, HostListener, output, signal } from '@angular/core';
import { TranslateModule } from '@ngx-translate/core';
import { LucideAngularModule, MonitorUp } from 'lucide-angular';

@Component({
  selector: 'omm-file-drop',
  imports: [LucideAngularModule, TranslateModule],
  templateUrl: './file-drop.html',
  styleUrl: './file-drop.scss',
})
export class FileDrop {
  fileDrop = output<File[]>();
  readonly icon = {
    upload: MonitorUp,
  };

  @HostListener('document:dragenter', ['$event']) onDragEnter(event: DragEvent) {
    if (!event.dataTransfer?.types?.includes('Files')) return;
    event.preventDefault();
    event.stopImmediatePropagation();
    this.active.set(true);
  }
  @HostListener('drop', ['$event']) onDrop(event: DragEvent) {
    this.onFileDrop(event);
    this.active.set(false);
  }

  @HostListener('body:dragover', ['$event'])
  onBodyDragOver(event: DragEvent) {
    event.preventDefault();
    event.stopPropagation();
  }
  @HostListener('body:drop', ['$event'])
  onBodyDrop(event: DragEvent) {
    event.preventDefault();
  }

  dragLeave(event: DragEvent) {
    this.active.set(false);
  }

  active = signal<boolean>(false);
  onFileDrop(event: DragEvent) {
    event.preventDefault();
    event.stopPropagation();
    const dataTransfer: DataTransfer | null = event.dataTransfer;
    if (dataTransfer) {
      if (dataTransfer?.items) {
        const files: File[] = [];
        for (let i = 0; i < dataTransfer.items.length; i++) {
          if (dataTransfer.items[i].kind === 'file') {
            const file = dataTransfer.items[i].getAsFile();
            if (file) files.push(file);
          }
        }
        dataTransfer.items.clear();
        this.fileDrop.emit(files);
      } else {
        const files = dataTransfer.files;
        dataTransfer.clearData();
        this.fileDrop.emit(Array.from(files));
      }
    }
  }
}
