import { Injectable, signal } from '@angular/core';

export type Breakpoint = 'phone' | 'tablet' | 'desktop';

const PHONE_QUERY = '(max-width: 599px)';
const TABLET_QUERY = '(min-width: 600px) and (max-width: 1199px)';
const DESKTOP_QUERY = '(min-width: 1200px)';
const TOUCH_QUERY = '(pointer: coarse)';

const VIRTUAL_KEYBOARD_THRESHOLD_PX = 150;

const TEXT_INPUT_TYPES = new Set([
  'text', 'email', 'password', 'search', 'tel', 'url', 'number',
]);

function isTextLikeFocusTarget(target: EventTarget | null): boolean {
  if (!(target instanceof Element)) return false;
  if (target instanceof HTMLTextAreaElement) return true;
  if (target instanceof HTMLInputElement) return TEXT_INPUT_TYPES.has(target.type);
  if (target instanceof HTMLElement) {
    if (target.isContentEditable) return true;
    const attr = target.getAttribute('contenteditable');
    if (attr === '' || attr === 'true' || attr === 'plaintext-only') return true;
  }
  return false;
}

@Injectable({ providedIn: 'root' })
export class EnvironmentService {
  readonly breakpoint = signal<Breakpoint>('desktop');
  readonly isTouch = signal<boolean>(false);
  readonly virtualKeyboardVisible = signal<boolean>(false);

  #queries: MediaQueryList[] = [];
  #touchQuery: MediaQueryList | null = null;
  #initialized = false;
  #hasTextFocus = false;
  #viewportShrunk = false;

  init() {
    if (this.#initialized) return;
    this.#initialized = true;

    if (typeof window === 'undefined' || typeof window.matchMedia !== 'function') return;

    const phone = window.matchMedia(PHONE_QUERY);
    const tablet = window.matchMedia(TABLET_QUERY);
    const desktop = window.matchMedia(DESKTOP_QUERY);
    this.#queries = [phone, tablet, desktop];

    const updateBreakpoint = () => {
      if (phone.matches) this.breakpoint.set('phone');
      else if (tablet.matches) this.breakpoint.set('tablet');
      else this.breakpoint.set('desktop');
    };
    for (const q of this.#queries) q.addEventListener('change', updateBreakpoint);
    updateBreakpoint();

    this.#touchQuery = window.matchMedia(TOUCH_QUERY);
    const updateTouch = () => this.isTouch.set(this.#touchQuery!.matches);
    this.#touchQuery.addEventListener('change', updateTouch);
    updateTouch();

    const recomputeKeyboard = () => {
      this.virtualKeyboardVisible.set(this.#hasTextFocus && this.#viewportShrunk);
    };

    document.addEventListener('focusin', (e) => {
      this.#hasTextFocus = isTextLikeFocusTarget(e.target);
      recomputeKeyboard();
    });
    document.addEventListener('focusout', () => {
      queueMicrotask(() => {
        this.#hasTextFocus = isTextLikeFocusTarget(document.activeElement);
        recomputeKeyboard();
      });
    });

    const vv = window.visualViewport;
    if (vv) {
      const onViewport = () => {
        this.#viewportShrunk =
          window.innerHeight - vv.height > VIRTUAL_KEYBOARD_THRESHOLD_PX;
        recomputeKeyboard();
      };
      vv.addEventListener('resize', onViewport);
      vv.addEventListener('scroll', onViewport);
      onViewport();
    }
  }
}
