import { Combobox, ComboboxInput, ComboboxPopupContainer } from '@angular/aria/combobox';
import { Listbox, Option } from '@angular/aria/listbox';
import { OverlayModule } from '@angular/cdk/overlay';
import { Component, computed, forwardRef, input, signal, viewChildren } from '@angular/core';
import { NG_VALUE_ACCESSOR } from '@angular/forms';
import { TranslateModule } from '@ngx-translate/core';
import { HashIcon, LucideAngularModule, XIcon } from 'lucide-angular';

@Component({
  selector: 'omm-tags-input',
  imports: [
    TranslateModule,
    Combobox,
    ComboboxInput,
    ComboboxPopupContainer,
    LucideAngularModule,
    Listbox,
    Option,
    OverlayModule,
  ],
  templateUrl: './tags-input.html',
  styleUrl: './tags-input.scss',
  providers: [
    {
      provide: NG_VALUE_ACCESSOR,
      useExisting: forwardRef(() => TagsInput),
      multi: true,
    },
  ],
  host: {
    class: 'omm-input',
  },
})
export class TagsInput {
  disabled = signal(false);
  allTags = input.required<string[]>();

  tagRemoveIcon = XIcon;

  options = viewChildren(Option);
  query = signal('');
  tags = signal<string[]>([]);
  tagSuggestions = computed(() =>
    this.allTags().filter(
      (t) => !this.tags().includes(t) && t.toLowerCase().indexOf(this.query().toLowerCase()) !== -1
    )
  );

  // -------- CVA --------
  #onChange: (val: string[]) => void = () => {};
  #onTouched: () => void = () => {};

  writeValue(value: string[] | null): void {
    this.tags.set(value || []);
  }
  registerOnChange(fn: (val: string[]) => void): void {
    this.#onChange = fn;
  }
  registerOnTouched(fn: () => void): void {
    this.#onTouched = fn;
  }
  setDisabledState(isDisabled: boolean): void {
    this.disabled.set(isDisabled);
  }

  onBlur() {
    if (this.query()) {
      this.addTag(this.query());
    }
    this.#onTouched();
  }

  onEnter(evt: Event) {
    evt.preventDefault();
    // stopPropagation keeps the keydown from bubbling to ngCombobox's host handler,
    // which would otherwise run select({commit: true}) and write the picked tag's
    // label back into the input, overwriting our just-cleared query.
    evt.stopPropagation();
    const activeOption = this.options().find(o => o.active());
    if (activeOption) {
      this.addTag(activeOption.value());
    } else if (this.query()) {
      this.addTag(this.query());
    }
  }

  addTag(tag: string) {
    if (tag && !this.tags().includes(tag)) {
      this.tags.set([...this.tags(), tag]);
      this.#emitChange();
    }
    this.query.set('');
  }

  removeTag(index: number) {
    this.tags.set(this.tags().filter((_, i) => i !== index));
    this.#emitChange();
  }

  onBackspace() {
    if (this.query().length === 0 && this.tags().length > 0) {
      this.tags.set([...this.tags().slice(0, -1)]);
      this.#emitChange();
    }
  }

  #emitChange() {
    this.#onChange([...this.tags()]);
  }
}
