import {
  ChangeDetectionStrategy,
  Component,
  ElementRef,
  computed,
  input,
  output,
  viewChild,
} from '@angular/core';
import { FormsModule } from '@angular/forms';
import { TranslatePipe } from '@ngx-translate/core';
import { ChevronDown, ChevronUp, LucideAngularModule, X } from 'lucide-angular';

@Component({
  selector: 'omm-pdf-find-bar',
  imports: [FormsModule, LucideAngularModule, TranslatePipe],
  templateUrl: './find-bar.html',
  styleUrl: './find-bar.scss',
  changeDetection: ChangeDetectionStrategy.OnPush,
})
export class FindBar {
  readonly query = input<string>('');
  readonly current = input<number>(0);
  readonly total = input<number>(0);

  readonly queryChange = output<string>();
  readonly prev = output<void>();
  readonly next = output<void>();
  readonly closed = output<void>();

  readonly icon = { prev: ChevronUp, next: ChevronDown, close: X };

  readonly input = viewChild.required<ElementRef<HTMLInputElement>>('input');

  readonly hasQuery = computed(() => this.query().length > 0);
  readonly noResults = computed(() => this.hasQuery() && this.total() === 0);
  readonly countLabel = computed(() => {
    if (!this.hasQuery()) return '';
    if (this.total() === 0) return '0';
    return `${this.current() + 1} / ${this.total()}`;
  });

  focus() {
    const el = this.input().nativeElement;
    el.focus();
    el.select();
  }

  onInput(value: string) {
    this.queryChange.emit(value);
  }

  onKeydown(e: KeyboardEvent) {
    if (e.key === 'Enter') {
      e.preventDefault();
      if (e.shiftKey) this.prev.emit();
      else this.next.emit();
    } else if (e.key === 'Escape') {
      e.preventDefault();
      this.closed.emit();
    }
  }
}
